function showToast(message) { const toast = $('#toast'); toast.textContent = message; toast.classList.add('show'); clearTimeout(showToast.timer); showToast.timer = setTimeout(() => toast.classList.remove('show'), 3200); }
function markToday(label = 'Práctica completada') { const progress = store.get('weekProgress', {}); progress[todayKey()] = true; store.set('weekProgress', progress); renderWeek(); refreshProgress(); showToast(`${label}. Lo pequeño también cuenta.`); }
