function stopAudio() { if (!audio) return; try { audio.master.gain.exponentialRampToValueAtTime(.0001, audio.ctx.currentTime + .18); setTimeout(() => { audio?.ctx.close(); audio = null; }, 220); } catch { audio = null; } }
function startAudio(mode = audioMode) { if (audio) return true; const AudioContext = window.AudioContext || window.webkitAudioContext; if (!AudioContext) { showToast('Tu navegador no admite sonido; continuaremos sin audio.'); return false; } const ctx = new AudioContext(); const master = ctx.createGain(); master.gain.value = .0001; master.connect(ctx.destination); const osc = ctx.createOscillator(); const filter = ctx.createBiquadFilter(); const presets = { lluvia: [174, 520], bosque: [220, 760], mar: [130, 360], blanco: [90, 1200] }; const [frequency, cutoff] = presets[mode] || presets.lluvia; osc.type = mode === 'blanco' ? 'triangle' : 'sine'; osc.frequency.value = frequency; filter.type = 'lowpass'; filter.frequency.value = cutoff; osc.connect(filter).connect(master); osc.start(); master.gain.exponentialRampToValueAtTime(.045, ctx.currentTime + .5); audio = { ctx, master, osc }; return true; }
function chime() { if (!audio) return; const o = audio.ctx.createOscillator(), g = audio.ctx.createGain(); o.type = 'sine'; o.frequency.value = 392; g.gain.setValueAtTime(.0001, audio.ctx.currentTime); g.gain.exponentialRampToValueAtTime(.035, audio.ctx.currentTime + .03); g.gain.exponentialRampToValueAtTime(.0001, audio.ctx.currentTime + .65); o.connect(g).connect(audio.master); o.start(); o.stop(audio.ctx.currentTime + .7); vibrate(18); }
