function timerView(type) { const [eyebrow, title, intro] = timerViews[type]; const minutes = ({ movement: 5, chairSquats: 6, walk: 8, mobility: 5, balance: 4, dance: 7 })[type]; return `<p class="eyebrow">${eyebrow}</p><h2 id="modalTitle">${title}</h2><p class="modal-intro">${intro}</p><div class="movement-visual"><div class="movement-dot"></div><span id="movementCue">Listo para moverte</span></div><div class="timer-label" id="timerLabel">Muévete sin dolor ni exigencia</div><div class="timer-display" id="timerDisplay">${String(minutes).padStart(2, '0')}:00</div><div class="modal-actions"><button class="button button-primary" id="timerStart">Comenzar</button><button class="button button-dark" id="timerReset">Reiniciar</button></div>${audioControls()}<p class="mini-note">Si algo duele, te marea o te falta el aire, detente. Cuidarte no es exigirte.</p>`; }
