function renderWeek() { const names = ['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'], today = new Date(), monday = new Date(today); monday.setDate(today.getDate() - ((today.getDay() + 6) % 7)); const progress = store.get('weekProgress', {}); $('#weekDays').innerHTML = names.map((name, i) => { const date = new Date(monday); date.setDate(monday.getDate() + i); const key = date.toISOString().slice(0, 10); const isToday = key === todayKey(); return `<div class="day ${isToday ? 'today' : ''}"><span>${name}</span><button aria-label="${name}, ${progress[key] ? 'completado' : 'sin completar'}" class="${progress[key] ? 'done' : ''}" data-day="${key}">${progress[key] ? '✓' : ''}</button></div>`; }).join(''); $$('.day button').forEach(button => button.addEventListener('click', () => { const p = store.get('weekProgress', {}); p[button.dataset.day] ? delete p[button.dataset.day] : p[button.dataset.day] = true; store.set('weekProgress', p); renderWeek(); refreshProgress(); })); }
function refreshProgress() { const progress = store.get('weekProgress', {}), now = Date.now(), count = Object.keys(progress).filter(key => { const age = (now - new Date(`${key}T00:00:00`).getTime()) / 86400000; return age >= -1 && age < 7; }).length; $('#progressCount').textContent = count; $('#progressBar').style.width = `${Math.min(count / 7 * 100, 100)}%`; $('#progressMessage').textContent = count === 0 ? 'Puedes empezar cuando te venga bien. No hay prisa.' : count === 1 ? 'Un día a la vez. Ya comenzaste.' : `${count} momentos de cuidado propio esta semana.`; }
