const categoryLabels = { mental: 'MENTAL', fisico: 'FÍSICO', social: 'SOCIAL', espiritual: 'ESPIRITUAL' };
const categoryClasses = { mental: 'mental-pill', fisico: 'mint-pill', social: 'peach-pill', espiritual: 'yellow-pill' };
const categoryIcons = { mental: '◌', fisico: '↗', social: '♡', espiritual: '✦' };
const defaultDurations = { mental: 4, fisico: 5, social: 3, espiritual: 4 };
const extraExercises = Object.entries(extraExerciseNames).flatMap(([category, items]) => items.map(([title, description], index) => ({ id: `extra-${category}-${index}`, title, description, category, duration: defaultDurations[category], instructions: `Busca una postura cómoda. ${description} Hazlo sin dolor ni exigencia y detente si algo no se siente bien.` })));
function exerciseCard(exercise, custom = false) { const category = exercise.category || 'mental'; return `<article class="exercise-card generated-exercise ${custom ? 'custom-exercise' : ''}" data-category="${category}" data-intents="calma energia conexion sentido"><div class="card-top"><span class="category-pill ${categoryClasses[category] || 'mental-pill'}">${categoryLabels[category] || 'PERSONAL'}</span><span class="duration">${exercise.duration || 5} min</span></div><div class="icon ${category === 'mental' ? 'lavender' : category === 'fisico' ? 'mint' : category === 'social' ? 'peach' : 'yellow'}">${categoryIcons[category] || '✦'}</div><h3>${exercise.title}</h3><p>${exercise.description}</p><button class="card-button custom-open" data-exercise-id="${exercise.id}">Empezar <span>→</span></button></article>`; }
function renderExtraExercises() { const grid = $('#exerciseGrid'); if (!grid || grid.dataset.extrasRendered) return; grid.insertAdjacentHTML('beforeend', extraExercises.map(exercise => exerciseCard(exercise)).join('')); grid.dataset.extrasRendered = 'true'; renderCustomExercises(); }
function getCustomExercises() { return store.get('customExercises', []); }
function renderCustomExercises() { const grid = $('#exerciseGrid'); if (!grid) return; grid.querySelectorAll('.custom-exercise').forEach(card => card.remove()); const custom = getCustomExercises(); if (custom.length) grid.insertAdjacentHTML('beforeend', custom.map(exercise => exerciseCard(exercise, true)).join('')); }
function builderView() { return `<p class="eyebrow">Herramienta de creación</p><h2 id="modalTitle">Crea tu propio ejercicio</h2><p class="modal-intro">Diseña una práctica a tu medida y guárdala en este dispositivo.</p><div class="builder-grid"><label>Nombre<input id="builderTitle" maxlength="70" placeholder="Ej. Pausa para volver a mí" /></label><label>Categoría<select id="builderCategory"><option value="mental">Mental</option><option value="fisico">Físico</option><option value="social">Social</option><option value="espiritual">Espiritual</option></select></label><label>Duración (minutos)<input id="builderDuration" type="number" min="1" max="120" value="5" /></label><label>Intensidad<select id="builderIntensity"><option>Suave</option><option>Moderada</option><option>Intensa</option></select></label></div><label>Objetivo o descripción<textarea id="builderDescription" rows="2" maxlength="220" placeholder="¿Qué quieres practicar y para qué?"></textarea></label><label>Instrucciones paso a paso<textarea id="builderInstructions" rows="5" maxlength="900" placeholder="1. Adopta una postura cómoda...&#10;2. Respira...&#10;3. Cierra con una reflexión..." ></textarea></label><label>Reflexión final<textarea id="builderReflection" rows="2" maxlength="220" placeholder="¿Cómo me siento después?" ></textarea></label><div class="modal-actions"><button class="button button-primary" id="saveCustomExercise">Guardar ejercicio</button><button class="button button-dark" id="cancelCustomExercise">Cancelar</button></div><p class="modal-intro" id="builderStatus"></p>`; }
function customExerciseView(exercise) { return `<p class="eyebrow">${categoryLabels[exercise.category] || 'PERSONAL'} · ${exercise.duration || 5} min</p><h2 id="modalTitle">${exercise.title}</h2><p class="modal-intro">${exercise.description}</p><div class="mini-note"><strong>Intensidad:</strong> ${exercise.intensity || 'Suave'}<br><strong>Instrucciones:</strong><br>${(exercise.instructions || '').replace(/\n/g, '<br>')}</div><div class="timer-label" id="customTimerLabel">A tu propio ritmo</div><div class="timer-display" id="customTimerDisplay">${String(exercise.duration || 5).padStart(2, '0')}:00</div><div class="modal-actions"><button class="button button-primary" id="startCustomTimer">Comenzar</button><button class="button button-dark" id="completeCustomExercise">Completar ✓</button></div><p class="modal-intro">${exercise.reflection ? `<strong>Al terminar:</strong> ${exercise.reflection}` : 'Al terminar, nota qué cambió en tu cuerpo o en tu ánimo.'}</p>`; }
function openCustomExercise(id) { const exercise = [...extraExercises, ...getCustomExercises()].find(item => item.id === id); if (!exercise) return; modalContent.innerHTML = customExerciseView(exercise); modalBackdrop.hidden = false; document.body.style.overflow = 'hidden'; let remaining = (exercise.duration || 5) * 60, interval; const display = $('#customTimerDisplay'); $('#startCustomTimer').addEventListener('click', () => { if (interval) return; $('#startCustomTimer').textContent = 'En curso…'; interval = setInterval(() => { remaining--; display.textContent = `${String(Math.floor(remaining / 60)).padStart(2, '0')}:${String(remaining % 60).padStart(2, '0')}`; if (remaining <= 0) { clearInterval(interval); interval = null; $('#customTimerLabel').textContent = 'Tiempo completado'; $('#startCustomTimer').textContent = 'Completado ✓'; } }, 1000); }); $('#completeCustomExercise').addEventListener('click', () => { clearInterval(interval); markToday('Ejercicio completado'); closeModal(); }); $('#modalClose').focus(); }
function openBuilder() { modalContent.innerHTML = builderView(); modalBackdrop.hidden = false; document.body.style.overflow = 'hidden'; $('#cancelCustomExercise').addEventListener('click', closeModal); $('#saveCustomExercise').addEventListener('click', () => { const title = $('#builderTitle').value.trim(), description = $('#builderDescription').value.trim(), instructions = $('#builderInstructions').value.trim(); if (!title || !description || !instructions) { $('#builderStatus').textContent = 'Completa nombre, objetivo e instrucciones.'; return; } const custom = getCustomExercises(); custom.push({ id: `custom-${Date.now()}`, title, description, instructions, reflection: $('#builderReflection').value.trim(), category: $('#builderCategory').value, duration: Math.min(120, Math.max(1, Number($('#builderDuration').value) || 5)), intensity: $('#builderIntensity').value }); store.set('customExercises', custom); renderCustomExercises(); closeModal(); showToast('Tu ejercicio quedó guardado en este dispositivo.'); }); $('#modalClose').focus(); }
renderExtraExercises(); $('#createExercise')?.addEventListener('click', () => openUnifiedNodeEditor({ taskMode: true })); $('#exerciseGrid')?.addEventListener('click', event => { const button = event.target.closest('.custom-open'); if (button) openCustomExercise(button.dataset.exerciseId); });

