// Editor unificado de nodos v3: lienzo visual, inspector y ejecución de flujos.
const logicNodeTypes = {
  start: { label: 'Inicio', icon: '▶', color: 'start', group: 'Flujo' },
  action: { label: 'Acción', icon: '◆', color: 'action', group: 'Flujo' },
  question: { label: 'Pregunta', icon: '?', color: 'question', group: 'Entrada' },
  event: { label: 'Evento', icon: '⚡', color: 'event', group: 'Entrada' },
  breathing: { label: 'Respiración', icon: '◌', color: 'breathing', group: 'Bienestar' },
  movement: { label: 'Movimiento', icon: '↗', color: 'movement', group: 'Bienestar' },
  timer: { label: 'Temporizador', icon: '◷', color: 'timer', group: 'Bienestar' },
  wait: { label: 'Esperar', icon: '⌛', color: 'timer', group: 'Flujo' },
  reflection: { label: 'Reflexión', icon: '✎', color: 'reflection', group: 'Bienestar' },
  condition: { label: 'Condición', icon: '◇', color: 'condition', group: 'Lógica' },
  compare: { label: 'Comparar', icon: '≡', color: 'condition', group: 'Lógica' },
  set: { label: 'Variable', icon: 'ƒ', color: 'variable', group: 'Lógica' },
  random: { label: 'Azar', icon: '✦', color: 'random', group: 'Lógica' },
  note: { label: 'Nota', icon: '▤', color: 'note', group: 'Utilidad' },
  end: { label: 'Cierre', icon: '■', color: 'end', group: 'Flujo' }
};
const escapeLogic = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[char]));
const nodeLabel = type => logicNodeTypes[type]?.label || 'Nodo';
const nodeMeta = type => logicNodeTypes[type] || logicNodeTypes.action;
const makeLogicNode = (type, index, x = 80, y = 80) => ({ id: `graph-${Date.now()}-${index}-${Math.random().toString(36).slice(2,6)}`, type, title: nodeLabel(type), text: '', x, y, duration: ['timer','wait'].includes(type) ? 5 : 0, next: '', nextTrue: '', nextFalse: '', nextA: '', nextB: '', variable: type === 'question' ? 'respuesta' : 'energia', value: '3', operator: '<', rule: '', event: 'al abrir el ejercicio' });
function unifiedEditorMarkup(taskMode = false) {
  const groups = Object.entries(Object.groupBy ? Object.entries(logicNodeTypes).reduce((out,[type,meta])=>{(out[meta.group]??=[]).push([type,meta]);return out;}, {}) : { Flujo: [['start',logicNodeTypes.start],['action',logicNodeTypes.action],['wait',logicNodeTypes.wait],['end',logicNodeTypes.end]], Entrada: [['question',logicNodeTypes.question],['event',logicNodeTypes.event]], Bienestar: [['breathing',logicNodeTypes.breathing],['movement',logicNodeTypes.movement],['timer',logicNodeTypes.timer],['reflection',logicNodeTypes.reflection]], Lógica: [['condition',logicNodeTypes.condition],['compare',logicNodeTypes.compare],['set',logicNodeTypes.set],['random',logicNodeTypes.random]], Utilidad: [['note',logicNodeTypes.note]] });
  return `<div class="graph-shell"><div class="graph-header"><div><p class="eyebrow">${taskMode ? 'Creador de tareas · flujo visual' : 'Graph editor · edición avanzada'}</p><h2 id="modalTitle">${taskMode ? 'Crea una tarea con nodos' : 'Construye tu flujo visual'}</h2><p class="modal-intro">${taskMode ? 'Define la tarea y después conecta cada paso como en Unity. Todo quedará disponible en tu biblioteca.' : 'Diseña experiencias como en Unity: organiza nodos, crea reglas y prueba la ruta antes de guardarla.'}</p></div><div class="graph-health"><span class="graph-health-dot"></span><span id="graphHealthText">Sin validar</span></div></div>${taskMode ? `<section class="task-meta-panel"><div class="task-meta-heading"><span class="task-meta-icon">✦</span><div><strong>Información de la tarea</strong><small>Estos datos aparecerán en tu tarjeta de ejercicios.</small></div></div><div class="task-meta-fields"><label>Nombre de la tarea<input id="taskTitle" maxlength="70" placeholder="Ej. Pausa para volver a mí"></label><label>Categoría<select id="taskCategory"><option value="mental">Mental</option><option value="fisico">Físico</option><option value="social">Social</option><option value="espiritual">Espiritual</option></select></label><label>Duración estimada<input id="taskDuration" type="number" min="1" max="120" value="5"></label><label>Intensidad<select id="taskIntensity"><option>Suave</option><option>Moderada</option><option>Intensa</option></select></label><label class="task-meta-wide">Objetivo o descripción<textarea id="taskDescription" rows="2" maxlength="220" placeholder="¿Qué quieres practicar y para qué?"></textarea></label><label class="task-meta-wide">Reflexión final<textarea id="taskReflection" rows="2" maxlength="220" placeholder="¿Cómo me siento después?"></textarea></label></div><p class="task-meta-status" id="taskMetaStatus"></p></section>` : ''}<div class="graph-toolbar"><label class="graph-add"><span>Nuevo nodo</span><select id="graphTypeToAdd">${groups.map(([group,types])=>`<optgroup label="${group}">${types.map(([type,meta])=>`<option value="${type}">${meta.icon} ${meta.label}</option>`).join('')}</optgroup>`).join('')}</select></label><button class="button button-primary" id="addGraphNode">＋ Añadir</button><button class="graph-tool-button" id="undoGraph" title="Ctrl+Z">↶ <span>Deshacer</span></button><button class="graph-tool-button" id="redoGraph" title="Ctrl+Y">↷ <span>Rehacer</span></button><span class="graph-toolbar-divider"></span><button class="graph-tool-button" id="centerGraph">⌂ Centrar</button><button class="graph-tool-button" id="autoLayoutGraph">✧ Ordenar</button><button class="graph-tool-button" id="validateGraph">✓ Validar</button><button class="graph-tool-button graph-run-button" id="runGraph">▶ Probar flujo</button><label class="graph-search">⌕<input id="graphSearch" placeholder="Buscar nodo…"></label><span class="graph-zoom" id="graphZoomLabel">100%</span></div><div class="graph-hint"><b>Conectar:</b> pulsa una salida y luego la entrada del destino. <span>Arrastra el encabezado para mover · rueda para zoom · Supr elimina · Ctrl+D duplica.</span></div><div class="graph-workspace"><div class="graph-canvas-wrap" id="graphCanvasWrap"><div class="graph-canvas" id="graphCanvas"><svg class="graph-connections" id="graphConnections" viewBox="0 0 2000 1300" preserveAspectRatio="none"><defs><marker id="graphArrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0,0 L9,4.5 L0,9 z" fill="#75aa91"/></marker><marker id="graphArrowTrue" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0,0 L9,4.5 L0,9 z" fill="#e58c74"/></marker><marker id="graphArrowFalse" markerWidth="9" markerHeight="9" refX="8" y="4.5" orient="auto"><path d="M0,0 L9,4.5 L0,9 z" fill="#9c87c5"/></marker><marker id="graphArrowRandom" markerWidth="9" height="9" refX="8" refY="4.5" orient="auto"><path d="M0,0 L9,4.5 L0,9 z" fill="#d5a650"/></marker></defs></svg><div id="graphNodes"></div><div class="graph-empty-state" id="graphEmptyState"><strong>Tu lienzo está vacío</strong><span>Añade un nodo o usa “Ordenar” para empezar.</span></div></div></div><aside class="graph-inspector" id="graphInspector"><div class="inspector-empty"><span>✦</span><strong>Selecciona un nodo</strong><p>Edita sus propiedades, reglas y conexiones desde aquí.</p></div></aside></div><div class="graph-footer"><span id="graphStatus" role="status">Los cambios se guardan como borrador en este dispositivo.</span><button class="button button-dark" id="clearGraph">Limpiar lienzo</button><button class="button button-primary" id="saveGraphExercise">${taskMode ? "Guardar tarea" : "Guardar ejercicio visual"}</button></div></div>`;
}
function openUnifiedNodeEditor(config = {}) {
  const taskMode = Boolean(config.taskMode);
  modalContent.innerHTML = unifiedEditorMarkup(taskMode); modalBackdrop.hidden = false; document.body.style.overflow = 'hidden';
  const old = taskMode ? null : (store.get('unityNodeDraft') || store.get('logicNodeDraft'));
  let nodes = old?.map((node, i) => ({ ...makeLogicNode(node.type || 'action', i, node.x ?? 80 + i * 300, node.y ?? 100), ...node })) || [makeLogicNode('start', 0, 70, 130), makeLogicNode('action', 1, 390, 130), makeLogicNode('end', 2, 710, 130)];
  if (!old) nodes[0].next = nodes[1].id, nodes[1].next = nodes[2].id;
  let zoom = 1, selected = nodes[0]?.id || null, dragging = null, connecting = null, running = false, runTimer = null;
  const history = [], redo = [];
  const wrap=$('#graphCanvasWrap'), canvas=$('#graphCanvas'), layer=$('#graphNodes'), svg=$('#graphConnections'), inspector=$('#graphInspector');
  const clamp = n => { n.x=Math.max(18,Math.min(1780,Number(n.x)||18)); n.y=Math.max(18,Math.min(1130,Number(n.y)||18)); };
  const getNode = id => nodes.find(n=>n.id===id);
  const targets = (node, branch) => branch === 'true' ? node.nextTrue : branch === 'false' ? node.nextFalse : branch === 'a' ? node.nextA : branch === 'b' ? node.nextB : node.next;
  const setTarget = (node, branch, id) => { if (branch==='true') node.nextTrue=id; else if(branch==='false') node.nextFalse=id; else if(branch==='a') node.nextA=id; else if(branch==='b') node.nextB=id; else node.next=id; };
  const outputPorts = node => node.type==='condition'||node.type==='compare' ? [['true','SÍ','port-true'],['false','NO','port-false']] : node.type==='random' ? [['a','A','port-a'],['b','B','port-b']] : [['next','salida','port-next']];
  const connectionList = node => outputPorts(node).map(([branch,label,cls]) => ({id:targets(node,branch),branch,label,cls}));
  const snapshot = () => JSON.stringify(nodes);
  const remember = () => { history.push(snapshot()); if(history.length>60)history.shift(); redo.length=0; store.set('unityNodeDraft',nodes); store.set('logicNodeDraft',nodes); };
  const restore = (state) => { nodes=JSON.parse(state); selected=getNode(selected)?.id || nodes[0]?.id || null; draw(); drawInspector(); };
  const undo = () => { if(!history.length)return; redo.push(snapshot()); restore(history.pop()); $('#graphStatus').textContent='Cambio deshecho.'; };
  const redoAction = () => { if(!redo.length)return; history.push(snapshot()); restore(redo.pop()); $('#graphStatus').textContent='Cambio rehecho.'; };
  const options = (current, selectedId='') => `<option value="">Sin conexión</option>${nodes.filter(n=>n.id!==current).map(n=>`<option value="${n.id}" ${selectedId===n.id?'selected':''}>${escapeLogic(nodeLabel(n.type))} · ${escapeLogic(n.title||'Sin título')}</option>`).join('')}`;
  const drawConnections = () => { svg.querySelectorAll('.graph-line,.graph-line-label').forEach(el=>el.remove()); nodes.forEach(source=>connectionList(source).forEach(route=>{ const target=getNode(route.id); if(!target)return; const x1=source.x+248,y1=source.y+62,x2=target.x,y2=target.y+62,bend=Math.max(70,Math.abs(x2-x1)*.45); const path=document.createElementNS('http://www.w3.org/2000/svg','path'); path.setAttribute('d',`M ${x1} ${y1} C ${x1+bend} ${y1}, ${x2-bend} ${y2}, ${x2} ${y2}`); path.setAttribute('class',`graph-line ${route.cls}`); path.setAttribute('marker-end',`url(#${route.branch==='true'?'graphArrowTrue':route.branch==='false'?'graphArrowFalse':route.branch==='a'||route.branch==='b'?'graphArrowRandom':'graphArrow'})`); if(running && source.id===selected)path.classList.add('active-line'); svg.appendChild(path); if(route.branch!=='next'){ const text=document.createElementNS('http://www.w3.org/2000/svg','text'); text.textContent=route.label; text.setAttribute('x',(x1+x2)/2); text.setAttribute('y',(y1+y2)/2-8); text.setAttribute('class','graph-line-label '+route.cls); svg.appendChild(text); } })); };
  const fieldInput = (label, field, value, placeholder='') => `<label class="inspector-field"><span>${label}</span><input data-inspector-field="${field}" value="${escapeLogic(value)}" placeholder="${placeholder}"></label>`;
  const drawInspector = () => { const node=getNode(selected); if(!node){inspector.innerHTML='<div class="inspector-empty"><span>✦</span><strong>Selecciona un nodo</strong><p>Edita sus propiedades, reglas y conexiones desde aquí.</p></div>';return;} const meta=nodeMeta(node.type), logical=['condition','compare','set','random'].includes(node.type), wait=['timer','wait'].includes(node.type); inspector.innerHTML=`<div class="inspector-head"><div class="inspector-icon ${meta.color}">${meta.icon}</div><div><span>Propiedades del nodo</span><h3>${escapeLogic(meta.label)}</h3></div><button class="inspector-close" id="deleteSelectedNode" title="Eliminar nodo">×</button></div><div class="inspector-body">${fieldInput('Título','title',node.title,'Nombre visible')}${fieldInput('Descripción / instrucción','text',node.text,'Qué ocurre en este paso')} ${wait?fieldInput('Duración (minutos)','duration',node.duration||5,'5'):''}${node.type==='question'?fieldInput('Guardar respuesta en','variable',node.variable||'respuesta','respuesta'):''}${node.type==='event'?fieldInput('Evento','event',node.event||'al abrir el ejercicio','al abrir…'):''}${node.type==='set'?`${fieldInput('Variable','variable',node.variable||'energia','energia')}${fieldInput('Asignar valor','value',node.value||'3','3')}`:''}${node.type==='condition'?fieldInput('Regla','rule',node.rule||'respuesta = sí','energia < 3 o respuesta = sí'):''}${node.type==='compare'?`<div class="inspector-grid">${fieldInput('Variable','variable',node.variable||'energia','energia')}<label class="inspector-field"><span>Operador</span><select data-inspector-field="operator"><option value="<" ${node.operator==='<'?'selected':''}>&lt; menor que</option><option value="=" ${node.operator==='='?'selected':''}>= igual a</option><option value=">" ${node.operator==='>'?'selected':''}>&gt; mayor que</option></select></label></div>${fieldInput('Comparar con','value',node.value||'3','3')}`:''}${(node.type==='condition'||node.type==='compare'||node.type==='random')?`<div class="inspector-section-title">Salidas y conexiones</div>`:''}<div class="inspector-connections">${outputPorts(node).map(([branch,label])=>`<label><span>${label}</span><select data-inspector-field="${branch==='next'?'next':'next'+branch[0].toUpperCase()+branch.slice(1)}">${options(node.id,targets(node,branch))}</select></label>`).join('')}</div><div class="inspector-section-title">Acciones</div><div class="inspector-actions"><button class="graph-tool-button" id="duplicateSelected">＋ Duplicar</button><button class="graph-tool-button" id="focusSelected">⌖ Enfocar</button></div></div>`;
    inspector.querySelectorAll('[data-inspector-field]').forEach(field=>{const update=()=>{remember();const n=getNode(selected);if(!n)return;n[field.dataset.inspectorField]=field.dataset.inspectorField==='duration'?Math.max(1,Math.min(120,Number(field.value)||1)):field.value;draw();drawInspector();};field.addEventListener('change',update);field.addEventListener('input',update);});
    $('#deleteSelectedNode').addEventListener('click',()=>removeNode(node.id)); $('#duplicateSelected').addEventListener('click',()=>duplicateNode(node.id)); $('#focusSelected').addEventListener('click',()=>focusNode(node));
  };
  const draw = () => { layer.innerHTML=nodes.map((node,index)=>{ clamp(node); const meta=nodeMeta(node.type), dim=$('#graphSearch')?.value?.trim().toLowerCase(), hidden=dim&&!`${node.title} ${meta.label} ${node.text}`.toLowerCase().includes(dim); return `<article class="graph-node ${selected===node.id?'selected':''} ${hidden?'search-hidden':''} ${running&&selected===node.id?'running-node':''}" data-node-id="${node.id}" data-type="${meta.color}" style="left:${node.x}px;top:${node.y}px"><div class="graph-node-head" data-drag-node="${node.id}"><span class="graph-node-title"><i>${meta.icon}</i><b>${escapeLogic(node.title||meta.label)}</b><small>${meta.label}</small></span><span class="graph-node-actions"><button type="button" data-duplicate-graph="${node.id}" title="Duplicar">＋</button><button type="button" data-remove-graph="${node.id}" title="Eliminar">×</button></span></div><span class="graph-port graph-port-in" data-connect-in="${node.id}" title="Entrada"></span><div class="graph-node-body"><p>${escapeLogic(node.text||'Sin descripción')}</p>${node.type==='condition'||node.type==='compare'?`<div class="node-rule">${escapeLogic(node.rule||`${node.variable||'variable'} ${node.operator||'='} ${node.value||'valor'}`)}</div>`:''}${node.type==='set'?`<div class="node-rule">${escapeLogic(node.variable||'variable')} ← ${escapeLogic(node.value||'valor')}</div>`:''}${['timer','wait'].includes(node.type)?`<span class="node-duration">◷ ${escapeLogic(node.duration||5)} min</span>`:''}</div>${outputPorts(node).map(([branch,label,cls])=>`<span class="graph-port graph-port-out ${cls}" data-connect-out="${node.id}" data-branch="${branch}" title="Salida ${label}">${branch==='next'?'':label}</span>`).join('')}</article>`; }).join(''); $('#graphEmptyState').classList.toggle('visible',!nodes.length); layer.querySelectorAll('[data-remove-graph]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();removeNode(b.dataset.removeGraph);})); layer.querySelectorAll('[data-duplicate-graph]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();duplicateNode(b.dataset.duplicateGraph);})); layer.querySelectorAll('.graph-node').forEach(el=>el.addEventListener('click',()=>{selected=el.dataset.nodeId;draw();drawInspector();})); layer.querySelectorAll('[data-drag-node]').forEach(head=>head.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();const n=getNode(head.dataset.dragNode);selected=n.id;dragging={node:n,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y};head.setPointerCapture?.(e.pointerId);drawInspector();})); layer.querySelectorAll('[data-connect-out]').forEach(port=>port.addEventListener('click',e=>{e.stopPropagation();connecting={nodeId:port.dataset.connectOut,branch:port.dataset.branch};layer.querySelectorAll('.graph-port-in').forEach(p=>p.classList.add('connect-target'));$('#graphStatus').textContent='Selecciona la entrada del nodo destino.';})); layer.querySelectorAll('[data-connect-in]').forEach(port=>port.addEventListener('click',e=>{e.stopPropagation();if(!connecting)return;remember();const source=getNode(connecting.nodeId);if(source&&source.id!==port.dataset.connectIn)setTarget(source,connecting.branch,port.dataset.connectIn);connecting=null;layer.querySelectorAll('.graph-port-in').forEach(p=>p.classList.remove('connect-target'));$('#graphStatus').textContent='Conexión creada.';draw();drawInspector();})); drawConnections(); };
  function removeNode(id){remember();nodes=nodes.filter(n=>n.id!==id);nodes.forEach(n=>['next','nextTrue','nextFalse','nextA','nextB'].forEach(k=>{if(n[k]===id)n[k]='';}));selected=nodes[0]?.id||null;draw();drawInspector();}
  function duplicateNode(id){const src=getNode(id);if(!src)return;remember();const copy={...src,...makeLogicNode(src.type,nodes.length,src.x+280,src.y+70),title:`${src.title||'Nodo'} copia`};nodes.push(copy);selected=copy.id;draw();drawInspector();}
  function focusNode(node){wrap.scrollTo({left:Math.max(0,node.x*zoom-150),top:Math.max(0,node.y*zoom-120),behavior:'smooth'});}
  function autoLayout(){remember();const start=nodes.find(n=>n.type==='start')||nodes[0];const levels=new Map(), queue=start?[start]:[];levels.set(start?.id||'',0);while(queue.length){const n=queue.shift(),level=levels.get(n.id);connectionList(n).forEach(r=>{const t=getNode(r.id);if(t&&!levels.has(t.id)){levels.set(t.id,level+1);queue.push(t);}});}nodes.forEach((n,i)=>{const level=levels.get(n.id)??Math.floor(i/3);const peers=nodes.filter(x=>(levels.get(x.id)??Math.floor(nodes.indexOf(x)/3))===level);n.x=70+level*330;n.y=90+peers.indexOf(n)*190;});draw();drawInspector();focusNode(start||nodes[0]);$('#graphStatus').textContent='Flujo ordenado de izquierda a derecha.';}
  function validate(){const errors=[];const start=nodes.filter(n=>n.type==='start');if(!start.length)errors.push('Falta un nodo Inicio.');if(start.length>1)errors.push('Hay más de un nodo Inicio.');nodes.forEach(n=>{if(['end','note'].includes(n.type))return;if(!connectionList(n).some(r=>r.id))errors.push(`“${n.title||nodeLabel(n.type)}” no tiene salida.`);connectionList(n).forEach(r=>{if(r.id===n.id)errors.push(`“${n.title}” se conecta consigo mismo.`);});});const reachable=new Set(),visit=id=>{if(!id||reachable.has(id))return;reachable.add(id);const n=getNode(id);connectionList(n||{}).forEach(r=>visit(r.id));};visit(start[0]?.id);nodes.filter(n=>!reachable.has(n.id)).forEach(n=>errors.push(`“${n.title||nodeLabel(n.type)}” no es alcanzable.`));const ok=!errors.length;$('#graphHealthText').textContent=ok?'Flujo válido':`${errors.length} alerta${errors.length===1?'':'s'}`;$('.graph-health-dot').classList.toggle('healthy',ok);$('#graphStatus').innerHTML=ok?'<b>✓ Flujo válido.</b> Puedes probarlo o guardarlo.':`<b>Revisa:</b> ${errors.slice(0,2).map(escapeLogic).join(' · ')}${errors.length>2?' · …':''}`;return ok;}
  function runFlow(){if(!validate()||running)return;running=true;const start=nodes.find(n=>n.type==='start');let current=start,steps=0;selected=start.id;draw();drawInspector();const tick=()=>{if(!running||!current||steps++>nodes.length+1){running=false;clearTimeout(runTimer);$('#graphStatus').textContent='Prueba finalizada.';draw();return;}selected=current.id;draw();drawInspector();const next=connectionList(current).find(r=>r.id)?.id;current=getNode(next);runTimer=setTimeout(tick,650);};tick();}
  wrap.addEventListener('pointermove',e=>{if(!dragging)return;dragging.node.x=dragging.x+(e.clientX-dragging.startX)/zoom;dragging.node.y=dragging.y+(e.clientY-dragging.startY)/zoom;draw();}); wrap.addEventListener('pointerup',()=>{if(dragging){remember();dragging=null;}}); wrap.addEventListener('pointerleave',()=>dragging=null); wrap.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.55,Math.min(1.6,zoom+(e.deltaY<0?.08:-.08)));canvas.style.transform=`scale(${zoom})`;$('#graphZoomLabel').textContent=`${Math.round(zoom*100)}%`;},{passive:false});
  $('#addGraphNode').addEventListener('click',()=>{remember();const type=$('#graphTypeToAdd').value,last=nodes[nodes.length-1],n=makeLogicNode(type,nodes.length,(last?.x||70)+300,((last?.y||120)+((nodes.length%3)*100))%900);nodes.push(n);selected=n.id;draw();drawInspector();}); $('#undoGraph').addEventListener('click',undo); $('#redoGraph').addEventListener('click',redoAction); $('#autoLayoutGraph').addEventListener('click',autoLayout); $('#validateGraph').addEventListener('click',validate); $('#runGraph').addEventListener('click',runFlow); $('#graphSearch').addEventListener('input',draw); $('#clearGraph').addEventListener('click',()=>{if(!nodes.length)return;remember();nodes=[];selected=null;draw();drawInspector();}); $('#centerGraph').addEventListener('click',()=>{zoom=1;canvas.style.transform='scale(1)';$('#graphZoomLabel').textContent='100%';wrap.scrollTo({left:0,top:0,behavior:'smooth'});});
  document.addEventListener('keydown',e=>{if(modalBackdrop.hidden)return;if(e.key==='Escape'&&connecting){connecting=null;layer.querySelectorAll('.graph-port-in').forEach(p=>p.classList.remove('connect-target'));return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redoAction();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'&&selected){e.preventDefault();duplicateNode(selected);}if((e.key==='Delete'||e.key==='Backspace')&&selected&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();removeNode(selected);}});
  $('#saveGraphExercise').addEventListener('click',()=>{if(!validate()||!nodes.length)return;const title=taskMode?$('#taskTitle').value.trim():(nodes.find(n=>n.type==='start')?.title||'Mi flujo visual');const description=taskMode?$('#taskDescription').value.trim():'Ejercicio creado en el editor avanzado de nodos.';if(taskMode&&!title){$('#taskMetaStatus').textContent='Escribe un nombre para la tarea antes de guardarla.';$('#taskTitle').focus();return;}if(taskMode&&!description){$('#taskMetaStatus').textContent='Añade un objetivo o descripción para que la tarea sea clara.';$('#taskDescription').focus();return;}store.set('unityNodeDraft',nodes);store.set('logicNodeDraft',nodes);const routeText=nodes.map((n,i)=>{const routes=connectionList(n).map(r=>`${r.label||'siguiente'} → ${getNode(r.id)?.title||'fin'}`).join(', ');return `${i+1}. [${nodeLabel(n.type)}] ${n.title}: ${n.text}${n.rule?` Regla: ${n.rule}.`:''} (${routes})`;}).join('\n');const custom=getCustomExercises();custom.push({id:`graph-${Date.now()}`,title,description,category:taskMode?$('#taskCategory').value:'mental',duration:taskMode?Math.min(120,Math.max(1,Number($('#taskDuration').value)||5)):Math.max(1,...nodes.map(n=>Number(n.duration)||0)),intensity:taskMode?$('#taskIntensity').value:'Suave',instructions:routeText,reflection:taskMode?$('#taskReflection').value.trim():'¿Qué ruta recorrí y qué aprendí?',graph:nodes,source:'node-editor'});store.set('customExercises',custom);renderCustomExercises();closeModal();showToast(taskMode?'Tarea creada desde el editor de nodos.':'Flujo visual guardado como ejercicio.');});
  draw();drawInspector();$('#modalClose').focus();
}
const nodeEditorButton=$('#openNodeEditor'); if(nodeEditorButton){nodeEditorButton.textContent='Editor avanzado de nodos ✦';nodeEditorButton.addEventListener('click',openUnifiedNodeEditor);}
